const approvedNames = new Set([]); // Añade hasta tres nombres de archivo exactos.
if (approvedNames.size < 1 || approvedNames.size > 3) {
  throw new Error('Configura de uno a tres archivos aprobados para la muestra.');
}
const selected = $input.all().filter(({ json }) =>
  typeof json.name === 'string' && /\.md$/iu.test(json.name) &&
  json.mimeType === 'text/markdown' && json.trashed !== true &&
  typeof json.id === 'string' && /^[A-Za-z0-9_-]+$/u.test(json.id) &&
  approvedNames.has(json.name) &&
  Number.isSafeInteger(Number(json.size)) && Number(json.size) > 0 &&
  Number(json.size) <= 65536
);
if (selected.length !== approvedNames.size ||
    new Set(selected.map(({ json }) => json.name)).size !== approvedNames.size) {
  throw new Error('Archivo Markdown faltante, duplicado o fuera del límite.');
}
return selected;

const inputs = $input.all();
const sizes = [];
for (let index = 0; index < inputs.length; index += 1) {
  const bytes = await this.helpers.getBinaryDataBuffer(index, 'data');
  const markdown = bytes.toString('utf8');
  if (bytes.length < 1 || bytes.length > 65536 || !markdown.trim() ||
      markdown.includes('\u0000') || !Buffer.from(markdown, 'utf8').equals(bytes)) {
    throw new Error('La muestra contiene un archivo inválido.');
  }
  sizes.push(bytes.length);
}
return [{ json: { checked: sizes.length, bytes: sizes, published: false } }];
